#!/usr/bin/env node
'use strict';
/* Audit-coverage freshness gate.
 *
 * The frozen audit pack is regenerated by scripts/export-audit-document.js, which
 * refuses to run when a page's recorded hash no longer matches its bytes. Nothing used
 * to catch that until someone tried to regenerate, so the pack silently rotted: it broke
 * on the default branch three times in a week, each time several commits after the page
 * edit that caused it, and each time it had to be traced back by hand.
 *
 * This moves the failure to the edit. It is deliberately cheap - hashing the public HTML files, no
 * DOM, no git - so it can sit in the normal suite.
 *
 * It checks three things:
 *   1. every public HTML page appears in the coverage inventory;
 *   2. the inventory names no page that no longer exists;
 *   3. every recorded sha256 matches the file on disk.
 *
 * A failure here is not a bug in the page. It means the review ledger has not been told
 * about a content change yet. The message says what to do.
 */
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const coverage = JSON.parse(fs.readFileSync(path.join(root, 'docs/page-audit/coverage.json'), 'utf8'));
const sha = file => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');

// Mirrors the exporter's own notion of a public page.
const SKIP = /^(?:docs|tests|scripts|audit|tmp|node_modules)\//;
function publicPages(dir = root, prefix = '') {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith('.')) continue;
    const rel = prefix ? prefix + '/' + entry.name : entry.name;
    if (SKIP.test(rel + '/')) continue;
    if (entry.isDirectory()) out.push(...publicPages(path.join(dir, entry.name), rel));
    else if (entry.name.endsWith('.html')) out.push(rel);
  }
  return out;
}

let passed = 0;
const problems = [];
const check = (ok, message) => { if (ok) passed++; else problems.push(message); };

const onDisk = publicPages().sort();
const recorded = coverage.pages.map(p => p.path).sort();

for (const page of onDisk) {
  check(recorded.includes(page),
    'public page missing from the coverage inventory: ' + page);
}
for (const page of recorded) {
  check(onDisk.includes(page),
    'coverage inventory names a page that no longer exists: ' + page);
}

const stale = [];
for (const entry of coverage.pages) {
  const file = path.join(root, entry.path);
  if (!fs.existsSync(file)) continue;
  const actual = sha(file);
  if (actual === entry.sha256) { passed++; continue; }
  stale.push(entry.path);
}
check(stale.length === 0,
  'recorded hashes are stale for ' + stale.length + ' page(s):\n    ' + stale.join('\n    ') +
  '\n\n  These pages changed without the review ledger being updated, so' +
  '\n  scripts/export-audit-document.js cannot regenerate the audit pack.' +
  '\n  Fix by recording what changed and why in docs/page-audit/coverage.json' +
  '\n  (sha256, words, and a note for each page), then:' +
  '\n      node scripts/export-audit-document.js --ref HEAD' +
  '\n      node scripts/export-audit-document.js --check' +
  '\n      python3 scripts/package-audit-document.py' +
  '\n  Refreshing a hash without saying what changed defeats the point of the ledger.');

// ---------------------------------------------------------------------------
// The pack's own programs. Page hashes cannot see a change here, and one slipped
// through: a commit registered a new input in the exporter without regenerating,
// so the manifest kept pointing at a commit where that input did not exist and
// the exporter refused to run at all. The manifest records these hashes at
// generation time precisely so a shallow CI checkout, which has no history to
// compare against source_commit, can still detect it.
const manifestPath = path.join(root, 'audit/manifest.json');
if (fs.existsSync(manifestPath)) {
  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  const gen = manifest.generator;
  check(!!gen, 'audit/manifest.json records no generator hashes; regenerate the pack so a change ' +
    'to the exporter or packager becomes detectable');
  if (gen) {
    for (const [file, recorded] of [[gen.exporter, gen.exporter_sha256], [gen.packager, gen.packager_sha256]]) {
      const onDisk = fs.existsSync(path.join(root, file)) ? sha(path.join(root, file)) : null;
      check(onDisk === recorded,
        file + ' has changed since the audit pack was generated' +
        '\n      recorded ' + String(recorded).slice(0, 16) + '…, on disk ' + String(onDisk).slice(0, 16) + '…' +
        '\n      What the pack contains is decided by these programs, so the pack is stale.' +
        '\n      Regenerate it:' +
        '\n          node scripts/export-audit-document.js --ref HEAD' +
        '\n          node scripts/export-audit-document.js --check' +
        '\n          python3 scripts/package-audit-document.py');
    }
  }
  // An input the exporter will read must still exist, or regeneration cannot run.
  const gone = (manifest.input_files || []).map(f => f.path)
    .filter(p => !fs.existsSync(path.join(root, p)));
  check(gone.length === 0,
    'the audit pack records inputs that no longer exist: ' + gone.slice(0, 5).join(', ') +
    (gone.length > 5 ? ' (+' + (gone.length - 5) + ' more)' : '') +
    '\n      Regenerate the pack so its input list matches the repository.');
}

if (problems.length) {
  console.error('\naudit-coverage-fresh: ' + problems.length + ' problem(s)\n');
  problems.forEach(p => console.error('  ✗ ' + p));
  console.error('');
  process.exit(1);
}
console.log('audit-coverage-fresh: ' + onDisk.length + ' public pages inventoried, ' +
  coverage.pages.length + ' recorded hashes current, exporter and packager unchanged since the pack was built.');
